#!/usr/bin/env python3
from pathlib import Path
import re,sys

if len(sys.argv)!=3: raise SystemExit('usage: integrate-SOT-turn01-base22-ui.py <pre-base.html> <base.html>')
src=Path(sys.argv[1]).read_text()
for m in ['<title>SOT Turn 01 Pre-Base</title>','TURN 01 · PRE-BASE',"const BUILD='SOT-turn01-pre-base';",'function newProject(){','async function renderScope(p){','async function openSourcePicker(p,current){','async function renderIndex(p){','function openConfig(){']:
    if src.count(m)!=1: raise SystemExit(f'pre-base UI contract failed for {m}: {src.count(m)}')

def span(text,name):
    ms=list(re.finditer(r'(?m)^(?:async\s+)?function\s+'+re.escape(name)+r'\s*\(',text))
    if len(ms)!=1: raise SystemExit(f'function {name} ambiguous {len(ms)}')
    a=ms[0].start(); b=text.find('{',ms[0].end()); d=0;q=None;e=False;i=b
    while i<len(text):
        c=text[i]
        if q:
            if e:e=False
            elif c=='\\':e=True
            elif c==q:q=None
        else:
            if c in "'\"`":q=c
            elif c=='{':d+=1
            elif c=='}':
                d-=1
                if d==0:return a,i+1
        i+=1
    raise SystemExit('unbalanced '+name)
def repl(text,name,val):
    a,b=span(text,name);return text[:a]+val.rstrip()+text[b:]

src=src.replace('<title>SOT Turn 01 Pre-Base</title>','<title>SOT Turn 01 Base</title>',1).replace('TURN 01 · PRE-BASE','TURN 01 · BASE',1).replace("const BUILD='SOT-turn01-pre-base';","const BUILD='SOT-turn01-base';",1)
